import{z as o,x as s,o as r,c as p,q as n,j as i,D as a,d as B,s as t,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"实验管理与配置工程","description":"","frontmatter":{"title":"实验管理与配置工程","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rw-experiment-config.md","filePath":"llm/rw-experiment-config.md","lastUpdated":1791063341000}'),d={name:"llm/rw-experiment-config.md"};function m(D,E,u,h,c,f){const A=s("Mermaid");return r(),p("div",null,[E[2]||(E[2]=n('<h1 id="实验管理与配置工程" tabindex="-1">实验管理与配置工程 <a class="header-anchor" href="#实验管理与配置工程" aria-label="Permalink to &quot;实验管理与配置工程&quot;">​</a></h1><div class="epigraph"><p>不可重复测量的量不是量，不可追溯来源的实验不算实验；账目先于结论。</p><footer>—— 据 Bouthillier 等, Accounting for Variance in Machine Learning Benchmarks, MLSys 2021 整理</footer></div><p><a href="/llm/rw-codebase-reading">上一课</a>把走读停在一步的产出物上。复现从这里开始变成「跑很多次」，而跑很多次的失败大多不是模型失败，是账目失败：两天后看着一条异常曲线，答不出「这个 run 用的是哪份配置、哪个数据快照、哪版代码」。训练基础设施课已经把账目工程讲透——run 身份四元组、配置哈希全链路同一、工件存指针不存副本，见<a href="/llm/ti-experiment-tracking">实验跟踪</a>与<a href="/llm/ti-recipe-management">训练配方管理</a>。本课只补复现场景特有的增量：账目要同时服务两边——你的实现与参考实现。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>复现实验的账比自研训练多一层义务：每个 run 不仅要能向自己解释，还要能与参考实现对质。缺口有三。其一，配置散落：脚本参数、环境变量、命令行历史各存一份，复现时「改了一点」没有记录，曲线从此无法解释。其二，环境漂移：两台机器、两次安装，库的次版本不同，行为差异被误判为方法差异。其三，数据无指纹：参考实现用的数据快照与自己重新下载的数据，清洗与去重细节不同，所有下游对比失真。</p><p><span class="marginnote">「配置哈希」就是给一份配置算出的指纹：同一份 YAML 算出的指纹永远相同，改一个字符指纹就变。拿指纹当 run 的名字，三个月后还能机械地验证「这个实验用的确实是这份配置」——这就是账目可比性的起点。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>配置即代码：所有实验参数收敛到单一入口（一份 YAML），从命令行历史与散落的 argparse 默认值里收权。配方字段按<a href="/llm/ti-recipe-management">训练配方管理</a>的六组组织——模型、数据、优化、数值、观测、治理；配方是指针的集合，指向数据快照、代码版本与评测脚本的具体版本。配置哈希是 run 的名字：跟踪、检查点、评测三处的哈希必须同一，这条在基础设施课是可比性地基，在复现里还是「与参考实现对照」的凭证——对账时先比哈希，哈希不同的一切比较作废。</p><p>环境冻结用锁文件加容器镜像，镜像哈希记入 run。数据不重新清洗：能拿到原快照就用原快照，拿不到就记指纹差异档位。种子分开管：初始化种子、数据顺序种子、dropout 种子各自独立，复现的方差测量（同配置多种子）依赖这种分离。实验矩阵由编排脚本生成——列出配置差分、程序化展开成 run，禁止手改单个 run 的配置；手改必漏记。</p><p><span class="marginnote">数字实例：两台机器只差 PyTorch 一个次版本（2.1 与 2.2），某个算子的默认实现换了，同配置的 loss 曲线在小数点后第三位分岔。没有锁文件与镜像，这类差异会被误判成「方法差异」，归因从第一步就走错方向。</span></p>',10)),(r(),i(l,null,{default:a(()=>[t(A,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20YAML%5B%22%E5%8D%95%E4%B8%80%E9%85%8D%E7%BD%AE%E5%85%A5%E5%8F%A3%22%5D%20--%3E%20HASH%5B%22%E9%85%8D%E7%BD%AE%E5%93%88%E5%B8%8C%22%5D%0A%20%20HASH%20--%3E%20T1%5B%22%E8%B7%9F%E8%B8%AA%E7%B3%BB%E7%BB%9F%22%5D%0A%20%20HASH%20--%3E%20T2%5B%22%E6%A3%80%E6%9F%A5%E7%82%B9%E7%9B%AE%E5%BD%95%22%5D%0A%20%20HASH%20--%3E%20T3%5B%22%E8%AF%84%E6%B5%8B%E8%AE%B0%E5%BD%95%22%5D%0A%20%20T1%20---%20T2%0A%20%20T2%20---%20T3%0A%20%20YAML%20--%3E%20LOCK%5B%22%E9%94%81%E6%96%87%E4%BB%B6%E4%B8%8E%E9%95%9C%E5%83%8F%22%5D%0A%20%20YAML%20--%3E%20FP%5B%22%E6%95%B0%E6%8D%AE%E6%8C%87%E7%BA%B9%22%5D%0A%20%20HASH%20--%3E%20RUN%5B%22run%20%E5%9B%9B%E5%85%83%E7%BB%84%EF%BC%9A%E5%93%88%E5%B8%8C%2B%E4%BB%A3%E7%A0%81%2B%E6%95%B0%E6%8D%AE%2B%E7%A7%8D%E5%AD%90%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[B("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,"为什么哈希全链路同一在复现里更严格：自研训练里哈希断裂只是自己麻烦，复现里它是证据链——「我复现的对象就是这个哈希对应的配置」这句话断了，后面所有数字失去资格。继承要显式：与基线的差异写成 diff，评审者几分钟内能说出你改了什么；复现报告一课的对齐账直接引用这份 diff。",-1)),E[5]||(E[5]=e("p",null,"为什么种子要分立与重复：Bouthillier 等 2021 把基准方差拆解成数据顺序、初始化、dropout 等成分，发现数据顺序一项的方差常不小于初始化——只锁初始化种子的「同配置重复」测不到主要噪声。复现要判断 0.3 分的差是信号还是噪声，先得有噪声的测量；种子数按目标容差与测得方差定，不是固定三个或五个。",-1)),(r(),i(l,null,{default:a(()=>[t(A,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E5%90%8C%E9%85%8D%E7%BD%AE%E9%87%8D%E5%A4%8D%E8%B7%91%EF%BC%8C%E8%AF%BB%E5%88%B0%E7%9A%84%E5%B7%AE%E5%BC%82%E6%98%AF%E4%BB%80%E4%B9%88%22%5D%20--%3E%20A%5B%22%E5%8F%AA%E9%94%81%E5%88%9D%E5%A7%8B%E5%8C%96%E7%A7%8D%E5%AD%90%22%5D%0A%20%20A%20--%3E%20VA%5B%22%E6%95%B0%E6%8D%AE%E9%A1%BA%E5%BA%8F%E4%B8%8E%20dropout%20%E7%9A%84%E6%96%B9%E5%B7%AE%E6%B5%8B%E4%B8%8D%E5%88%B0%22%5D%0A%20%20VA%20--%3E%20WA%5B%22%E5%99%AA%E5%A3%B0%E8%A2%AB%E4%BD%8E%E4%BC%B0%EF%BC%9A%E5%81%87%E4%BF%A1%E5%8F%B7%E8%A2%AB%E5%BD%93%E6%88%90%E7%9C%9F%E5%B7%AE%E5%BC%82%22%5D%0A%20%20Q%20--%3E%20B%5B%22%E4%B8%89%E7%B1%BB%E7%A7%8D%E5%AD%90%E5%90%84%E8%87%AA%E5%88%86%E7%AB%8B%E9%87%8D%E6%8A%BD%22%5D%0A%20%20B%20--%3E%20VB%5B%22%E5%99%AA%E5%A3%B0%E5%B8%A6%E8%A6%86%E7%9B%96%E5%85%A8%E9%83%A8%E9%9A%8F%E6%9C%BA%E6%80%A7%E6%9D%A5%E6%BA%90%22%5D%0A%20%20VB%20--%3E%20WB%5B%22%E5%B8%A6%E5%86%85%E7%AE%97%E5%99%AA%E5%A3%B0%EF%BC%8C%E5%B8%A6%E5%A4%96%E6%89%8D%E5%8F%AB%E4%BF%A1%E5%8F%B7%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=n('<p><span class="marginnote">直觉类比：把训练想成掷骰子——初始化是开局那把骰子，数据顺序是发牌次序，dropout 是每局中途的手抖。三副骰子只锁死一副，你永远说不清波动来自哪一副；分开锁，波动才能归到具体来源。</span></p><p><span class="marginnote">工件存指针不存副本：run 里记检查点与数据集的指针与指纹，不复制文件本体；权威在检查点分线目录（<a href="/llm/ti-checkpoint-engineering">checkpoint 工程深入</a>）。复现报告里贴曲线截图而不贴 run 链接，是最常见的账目倒退。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>账目不是越全越好：自动采集的部分（哈希、指纹、指标）机器写，人工只填动机与判词——「为什么跑这个配置」「预期对上什么」，这两个字段是三个月后唯一无法从别处恢复的。配置系统不做图灵完备：没有循环没有条件逻辑，表达不了的就写进代码而不是写进 YAML。超参搜索是另一门课的工程（<a href="/llm/ti-hparam-search-eng">超参搜索工程</a>）：复现里允许的搜索只有两类——环境重适配（让参考配置在你的硬件上跑起来）与基线重调（服务基线校准），都要在报告里单列，不与复现本身混淆。逐位一致不设为目标，跨硬件的数值一致性是独立工程，本课的容差从声明（第一课）继承。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>配置收敛到单一入口，哈希贯穿跟踪、检查点、评测三处；哈希不同的一切比较作废。</li><li>环境用锁文件与镜像冻结；数据优先用原快照，否则记指纹差异档位。</li><li>种子分立（初始化、数据顺序、dropout），同配置多种子测噪声，种子数按容差定。</li><li>实验矩阵由脚本生成，禁止手改单个 run；人工只填动机与判词。</li><li>出处：Bouthillier 等, 2021；口径见<a href="/llm/ti-experiment-tracking">实验跟踪</a>与<a href="/llm/ti-recipe-management">训练配方管理</a>。</li></ul>',6))])}const T=o(d,[["render",m]]);export{C as __pageData,T as default};
